#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package Microsoft.CodeAnalysis.CSharp@4.7.0 #:package Microsoft.CodeAnalysis.Analyzers@3.3.4 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Text; using Microsoft.CodeAnalysis; using Microsoft.CodeAnalysis.Text;  [Generator] public class DtoGenerator : ISourceGenerator {     public void Initialize(GeneratorInitializationContext context)     {         context.RegisterForSyntaxNotifications(() => new DtoSyntaxReceiver());     }      public void Execute(GeneratorExecutionContext context)     {         if (!(context.SyntaxContextReceiver is DtoSyntaxReceiver receiver))             return;          foreach (var dtoInfo in receiver.DtoClasses)         {             var source = GenerateDtoClass(dtoInfo);             context.AddSource($"{dtoInfo.Name}Dto.g.cs", SourceText.From(source, Encoding.UTF8));         }     }      private string GenerateDtoClass(DtoInfo dtoInfo)     {         var sb = new StringBuilder();         sb.AppendLine("// <auto-generated/>");         sb.AppendLine("using System;");         sb.AppendLine();         sb.AppendLine($"namespace {dtoInfo.Namespace}");         sb.AppendLine("{");         sb.AppendLine($"    public partial class {dtoInfo.Name}Dto");         sb.AppendLine("    {");                  foreach (var prop in dtoInfo.Properties)         {             sb.AppendLine($"        public {prop.Type} {prop.Name} {{ get; set; }}");         }                  sb.AppendLine("    }");         sb.AppendLine("}");                  return sb.ToString();     } }  public class DtoSyntaxReceiver : ISyntaxContextReceiver {     public List<DtoInfo> DtoClasses { get; } = new();      public void OnVisitSyntaxNode(GeneratorSyntaxContext context)     {         if (context.Node is ClassDeclarationSyntax classDecl &&             classDecl.AttributeLists.Any(a => a.Attributes.Any(at => at.Name.ToString().Contains("Dto"))))         {             var model = context.SemanticModel.GetDeclaredSymbol(classDecl);             if (model != null)             {                 var dtoInfo = new DtoInfo                 {                     Name = model.Name,                     Namespace = model.ContainingNamespace.ToDisplayString(),                     Properties = model.GetMembers()                         .OfType<IPropertySymbol>()                         .Select(p => new PropertyInfo                         {                             Name = p.Name,                             Type = p.Type.ToDisplayString()                         })                         .ToList()                 };                 DtoClasses.Add(dtoInfo);             }         }     } }  public class DtoInfo {     public string Name { get; set; }     public string Namespace { get; set; }     public List<PropertyInfo> Properties { get; set; } }  public class PropertyInfo {     public string Name { get; set; }     public string Type { get; set; } }
